import React, { useEffect, useRef } from 'react';
import { Mic, Square, Trash2, Send } from 'lucide-react';
import { useVoiceRecorder } from '../../hooks/useVoiceRecorder';
import { formatDuration } from '../../utils/helpers';
import { Button, Tooltip } from '../ui';

/**
 * VoiceRecorder
 * Props:
 *  - onSend(blob: Blob) : called when user confirms the recording
 *  - disabled: boolean
 */
export default function VoiceRecorder({ onSend, disabled }) {
  const { isRecording, audioBlob, duration, error, startRecording, stopRecording, clearRecording } = useVoiceRecorder();
  const barsRef = useRef([]);

  // Animate waveform bars while recording
  useEffect(() => {
    if (!isRecording) {
      barsRef.current.forEach(b => { if (b) b.style.height = '4px'; });
      return;
    }
    const interval = setInterval(() => {
      barsRef.current.forEach(b => {
        if (b) b.style.height = `${4 + Math.random() * 20}px`;
      });
    }, 120);
    return () => clearInterval(interval);
  }, [isRecording]);

  const handleSend = () => {
    if (audioBlob) {
      onSend(audioBlob);
      clearRecording();
    }
  };

  return (
    <div style={styles.wrapper}>
      {error && (
        <p style={styles.error}>{error}</p>
      )}

      {/* Idle: show mic button */}
      {!isRecording && !audioBlob && (
        <Tooltip text="Record voice message">
          <button
            onClick={startRecording}
            disabled={disabled}
            style={{
              ...styles.micBtn,
              opacity: disabled ? 0.4 : 1,
              cursor: disabled ? 'not-allowed' : 'pointer',
            }}
            aria-label="Start recording"
          >
            <Mic size={18} color="var(--text-secondary)" />
          </button>
        </Tooltip>
      )}

      {/* Recording state */}
      {isRecording && (
        <div style={styles.recording}>
          {/* Live waveform */}
          <div style={styles.waveform}>
            {Array.from({ length: 12 }).map((_, i) => (
              <span
                key={i}
                ref={el => barsRef.current[i] = el}
                style={{
                  ...styles.bar,
                  animationDelay: `${i * 50}ms`,
                  background: i % 2 === 0 ? 'var(--accent-primary)' : 'var(--accent-primary)80',
                }}
              />
            ))}
          </div>

          <span style={styles.timer}>{formatDuration(duration)}</span>

          <button onClick={stopRecording} style={styles.stopBtn} aria-label="Stop recording">
            <Square size={14} fill="white" color="white" />
          </button>
        </div>
      )}

      {/* Preview state: blob ready */}
      {audioBlob && !isRecording && (
        <div style={styles.preview}>
          <div style={styles.previewIcon}>
            <Mic size={14} color="var(--accent-primary)" />
          </div>
          <span style={styles.previewLabel}>
            {formatDuration(duration)} voice message
          </span>
          <audio src={URL.createObjectURL(audioBlob)} controls
            style={{ height: '28px', flex: 1, maxWidth: '140px' }} />

          <Tooltip text="Discard">
            <button onClick={clearRecording} style={styles.iconBtn} aria-label="Discard recording">
              <Trash2 size={15} color="var(--accent-rose)" />
            </button>
          </Tooltip>

          <Tooltip text="Send voice message">
            <button onClick={handleSend} style={{ ...styles.iconBtn, ...styles.sendBtn }}
              aria-label="Send voice message">
              <Send size={15} color="white" />
            </button>
          </Tooltip>
        </div>
      )}
    </div>
  );
}

const styles = {
  wrapper: { display: 'flex', alignItems: 'center', gap: '8px' },
  error: { fontSize: '11px', color: 'var(--accent-rose)', maxWidth: '200px' },
  micBtn: {
    width: '38px', height: '38px',
    background: 'var(--bg-elevated)',
    border: '1px solid var(--border)',
    borderRadius: 'var(--radius-md)',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    transition: 'background 150ms, border-color 150ms',
    flexShrink: 0,
  },
  recording: {
    display: 'flex', alignItems: 'center', gap: '10px',
    background: 'rgba(196,181,253,0.08)',
    border: '1px solid var(--border-accent)',
    borderRadius: 'var(--radius-lg)',
    padding: '6px 12px',
  },
  waveform: {
    display: 'flex', alignItems: 'center', gap: '3px', height: '28px',
  },
  bar: {
    width: '3px', borderRadius: '2px',
    height: '4px', transition: 'height 120ms ease',
    display: 'inline-block',
  },
  timer: {
    fontSize: '12px', fontWeight: 600, color: 'var(--accent-primary)',
    fontVariantNumeric: 'tabular-nums', minWidth: '36px',
  },
  stopBtn: {
    width: '28px', height: '28px', borderRadius: '50%',
    background: 'var(--accent-rose)',
    border: 'none', cursor: 'pointer',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
  },
  preview: {
    display: 'flex', alignItems: 'center', gap: '8px',
    background: 'var(--bg-elevated)',
    border: '1px solid var(--border)',
    borderRadius: 'var(--radius-lg)',
    padding: '6px 10px',
  },
  previewIcon: {
    width: '26px', height: '26px',
    background: 'var(--accent-glow)', border: '1px solid var(--border-accent)',
    borderRadius: 'var(--radius-sm)',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
  },
  previewLabel: {
    fontSize: '12px', color: 'var(--text-secondary)', whiteSpace: 'nowrap',
  },
  iconBtn: {
    background: 'none', border: 'none', cursor: 'pointer',
    padding: '4px', borderRadius: 'var(--radius-sm)',
    display: 'flex', alignItems: 'center',
  },
  sendBtn: {
    background: 'var(--accent-primary)', padding: '6px 10px', borderRadius: 'var(--radius-md)',
  },
};
